    var pk;window.NV_MAP_PICKER($('#locMap'),{lat:a.lat,lng:a.lng},function(ll){a.lat=ll.lat;a.lng=ll.lng;$('#locXY').textContent='Точка: '+ll.lat+', '+ll.lng;markDirty();var nb=$('.ed-nav button[data-s="loc"] span');if(nb)nb.textContent=(a.complex||'')+' · точка на карте'}).then(function(p){pk=p}).catch(function(){$('#locMap').innerHTML='<div class="empty">Карта не загрузилась — проверьте интернет</div>'});
