/* ---------- upload with browser-side compression ---------- */
var UP={files:[],target:null,cb:null};
function openUpload(a,opts){opts=opts||{};UP.files=[];UP.target=a;UP.single=!!opts.single;UP.cb=opts.cb||null;$('#upList').innerHTML='';$('#upSub').textContent='Ничего не выбрано';$('#upGo').disabled=true;$('#upModal').hidden=false}
$('#upX').onclick=function(){$('#upModal').hidden=true};
$('#upBrowse').onclick=$('#upAdd').onclick=function(){$('#upFile').click()};
$('#upFile').onchange=function(){addFiles(this.files);this.value=''};
var drop=$('#drop');['dragenter','dragover'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();drop.classList.add('over')})});['dragleave','drop'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();drop.classList.remove('over')})});
drop.addEventListener('drop',function(e){addFiles(e.dataTransfer.files)});
function isHeic(f){return /heic|heif/i.test(f.type)||/\.(heic|heif)$/i.test(f.name||'')}
function loadJs(src,glob){return new Promise(function(res,rej){if(window[glob])return res(window[glob]);var s=document.createElement('script');s.src=src;s.onload=function(){window[glob]?res(window[glob]):rej(new Error('lib'))};s.onerror=function(){rej(new Error('Не удалось загрузить конвертер HEIC'))};document.head.appendChild(s)})}
function heicConvert(blob){/* new libheif (modern iPhone HEIC) first, old heic2any as fallback */
  return loadJs('https://unpkg.com/heic-to@1/dist/iife/heic-to.js','HeicTo').then(function(H){var fn=typeof H==='function'?H:(H.heicTo||H.default);return fn({blob:blob,type:'image/jpeg',quality:.92})})
  .catch(function(e1){return loadJs('https://unpkg.com/heic2any@0.0.4/dist/heic2any.min.js','heic2any').then(function(h){return h({blob:blob,toType:'image/jpeg',quality:.92})}).then(function(b){return Array.isArray(b)?b[0]:b}).catch(function(){throw new Error('Этот HEIC не читается в браузере. Откройте фото в «Просмотре» → Файл → Экспорт → JPEG, или загрузите через Safari')})})}
function canDecode(blob){return new Promise(function(res){var u=URL.createObjectURL(blob),i=new Image();i.onload=function(){URL.revokeObjectURL(u);res(true)};i.onerror=function(){URL.revokeObjectURL(u);res(false)};i.src=u})}
function normalize(it){if(it.ready)return it.ready;it.ready=(isHeic(it.file)?canDecode(it.file).then(function(ok){if(ok)return it.file;it.conv=true;drawUp();return heicConvert(it.file)}):Promise.resolve(it.file)).then(function(b){it.src=b;it.conv=false;if(it.url)URL.revokeObjectURL(it.url);it.url=URL.createObjectURL(b);drawUp();return b}).catch(function(e){it.err=e.message||'Не удалось прочитать файл';it.conv=false;drawUp();throw e});return it.ready}
function addFiles(list){[].slice.call(list).filter(function(f){return /^image\//.test(f.type)||isHeic(f)}).forEach(function(f){if(UP.single)UP.files=[];var it={file:f,url:isHeic(f)?'':URL.createObjectURL(f),done:0};UP.files.push(it);normalize(it).catch(function(){})});drawUp()}
function drawUp(){$('#upList').innerHTML=UP.files.map(function(it,i){return '<div class="upi'+(it.err?' err':'')+'">'+(it.url?'<img src="'+it.url+'">':'<div class="conv"><i class="ph-bold ph-spinner"></i><small>HEIC…</small></div>')+(it.err?'<div class="emsg">'+esc(it.err)+'</div>':'')+'<span class="sz">'+(it.size?it.size:Math.round(it.file.size/1024)+' КБ')+'</span><div class="bar"><i style="width:'+it.done+'%"></i></div>'+(it.done?'':'<button class="rm" data-i="'+i+'"><i class="ph-bold ph-x"></i></button>')+'</div>'}).join('');$('#upSub').textContent=UP.files.length?UP.files.length+' фото выбрано':'Ничего не выбрано';$('#upGo').disabled=!UP.files.length;
  $$('#upList .rm').forEach(function(b){b.onclick=function(){UP.files.splice(+b.dataset.i,1);drawUp()}})}
function compress(file,maxW,q){return new Promise(function(res,rej){var img=new Image();img.onload=function(){var s=Math.min(1,maxW/Math.max(img.width,img.height));var w=Math.round(img.width*s),h=Math.round(img.height*s);var c=document.createElement('canvas');c.width=w;c.height=h;var x=c.getContext('2d');x.imageSmoothingQuality='high';x.drawImage(img,0,0,w,h);c.toBlob(function(b){b?res({blob:b,w:w,h:h}):rej(new Error('compress'))},'image/webp',q)};img.onerror=function(){rej(new Error('Не удалось прочитать '+(file.name||'фото')+' — формат не поддерживается'))};img.src=URL.createObjectURL(file)})}
function putImg(key,blob){return fetch(API+'/admin/upload?key='+encodeURIComponent(key),{method:'PUT',headers:{Authorization:'Bearer '+TOKEN,'Content-Type':(/^image\/(webp|jpeg|png)$/.test(blob.type)?blob.type:'image/webp')},body:blob}).then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d.message||d.error||'upload');return d})})}
$('#upGo').onclick=function(){var b=this;if(!UP.files.length||b.disabled)return;var a=UP.target||{};var prefix=UP.cb?'blog':(a.id||'misc');var out=[],lastErr='',LBL=b.dataset.lbl||(b.dataset.lbl=b.textContent);b.disabled=true;b.classList.add('busy');var total=UP.files.length;function lbl(k){b.textContent='Загружаем '+k+' из '+total+'…'}lbl(1);
  (function next(i){if(i>=UP.files.length){b.disabled=false;b.classList.remove('busy');b.textContent=LBL;if(!out.length){toast(lastErr?'Не загружено: '+lastErr:'Не удалось загрузить фото');return}$('#upModal').hidden=true;if(UP.cb)UP.cb(out[0]);else{a.photos=(a.photos||[]).concat(out);markDirty();render();toast(out.length===UP.files.length?out.length+' фото загружено — нажмите «Опубликовать»':'Загружено '+out.length+' из '+UP.files.length+(lastErr?' · '+lastErr:''))}return}
    var it=UP.files[i];var id=Date.now().toString(36)+Math.random().toString(36).slice(2,6);
    if(it.done===100){next(i+1);return}
    lbl(i+1);it.err='';it.done=8;drawUp();
    normalize(it).then(function(src){return Promise.all([compress(src,1600,.82),compress(src,480,.75)])}).then(function(r){it.size=Math.round(r[0].blob.size/1024)+' КБ';it.done=30;drawUp();return putImg(prefix+'/'+id+'.webp',r[0].blob).then(function(){it.done=70;drawUp();return putImg(prefix+'/'+id+'_t.webp',r[1].blob)}).then(function(){it.done=100;drawUp();out.push({k:prefix+'/'+id+'.webp',t:prefix+'/'+id+'_t.webp',w:r[0].w,h:r[0].h})})}).catch(function(e){lastErr=e&&e.message||'ошибка';it.err=lastErr;drawUp()}).then(function(){next(i+1)})})(0)};

