function calcTotal(aptId,fr,to){var A=S.draft.apts[aptId];if(!(A&&A.price&&fr&&to&&to>fr))return null;var n=Math.round((new Date(to)-new Date(fr))/864e5);var sub=A.price*n,dp=n>=30?20:n>=7?10:0;return {n:n,price:A.price,dp:dp,total:sub-Math.round(sub*dp/100)}}
