function refreshBg(){if(S.tab==='bookings'||S.tab==='today')render()}
function openNewBooking(){var c=openSheet('<div class="sh-h"><h2>Новая бронь</h2><button class="icon" id="shX"><i class="ph-bold ph-x"></i></button></div><p class="muted small" style="margin:-8px 0 0">Бронь сразу подтверждается, закрывает даты на сайте и уходит в Realty Calendar через импорт.</p>'+
  '<div class="form" style="gap:12px"><label>Апартамент<select id="nApt">'+aptOptions()+'</select></label><div class="row"><label>Заезд<input type="date" id="nFrom" min="'+today()+'"></label><label>Выезд<input type="date" id="nTo"></label></div><div class="row"><label>Гостей<input type="number" id="nG" min="1" max="10" value="2"></label><label>Сумма<input id="nTot" placeholder="авто"></label></div><label>Время заезда<input id="nArr" value="14:00" placeholder="14:00"></label><label>Имя гостя<input id="nName" autocomplete="off"></label><div class="row"><label>Телефон<input id="nPhone" type="tel" placeholder="+998 90 000 00 00"></label><label>Мессенджер<select id="nMsg"><option>Telegram</option><option>WhatsApp</option><option value="">—</option></select></label></div><label>Email <small>необязательно</small><input id="nEmail" type="email"></label><label>Источник<select id="nSrc"><option value="telegram">Telegram / WhatsApp</option><option value="call">Звонок</option><option value="instagram">Instagram</option><option value="repeat">Повторный гость</option><option value="partner">Партнёр</option></select></label><label>Заметка<textarea id="nNote" style="min-height:70px"></textarea></label><div class="err" id="nErr" hidden></div><button class="btn primary w100" id="nGo"><i class="ph-bold ph-check"></i>Создать бронь</button></div>');
  $('#shX',c).onclick=closeSheet;
  var recalc=function(){var r=calcTotal($('#nApt').value,$('#nFrom').value,$('#nTo').value);$('#nTot').placeholder=r?'$'+r.total:'авто'};
  ['#nApt','#nFrom','#nTo'].forEach(function(s){$(s).onchange=function(){if(s==='#nFrom'&&!$('#nTo').value){var d=new Date($('#nFrom').value);d.setDate(d.getDate()+1);$('#nTo').value=d.toISOString().slice(0,10)}$('#nTo').min=$('#nFrom').value;recalc()}});
  $('#nGo').onclick=function(){var self=this,er=$('#nErr');er.hidden=true;var tot=$('#nTot').value.trim()||($('#nTot').placeholder!=='авто'?$('#nTot').placeholder:'');if(tot&&!/^\$/.test(tot))tot='$'+tot.replace(/[^\d.]/g,'');var ap=$('#nApt').value;self.disabled=true;
    api('/admin/bookings',{method:'POST',json:{apt:ap,from:$('#nFrom').value,to:$('#nTo').value,guests:$('#nG').value,total:tot,name:$('#nName').value,phone:$('#nPhone').value,messenger:$('#nMsg').value,email:$('#nEmail').value,source:$('#nSrc').value,note:$('#nNote').value,arrival:$('#nArr').value,title:aptName(ap)}}).then(function(d){toast('Бронь '+d.booking.id+' создана');S.bookings=null;closeSheet();S.tab='bookings';render()}).catch(function(e){er.textContent=e.message;er.hidden=false;self.disabled=false})}}

