var gQ='';
function rGuests(v){v.innerHTML='<div class="empty">Загружаем…</div>';api('/admin/guests').then(function(d){var G=d.guests,q=gQ.toLowerCase();var L=q?G.filter(function(g){return (g.name+' '+g.phone+' '+(g.email||'')).toLowerCase().indexOf(q)>-1}):G;
  var tot=G.reduce(function(a,g){return a+g.spent},0),rep=G.filter(function(g){return g.bookings>1}).length;
  v.innerHTML='<div class="page-h"><h1>База гостей</h1><div class="bk-tools"><input type="search" id="gQ" placeholder="Имя, телефон, email" value="'+esc(gQ)+'"><button class="btn soft" id="gCsv"><i class="ph-bold ph-download-simple"></i>Excel (CSV)</button></div></div>'+
  '<div class="kpis" style="max-width:none"><div class="card kpi"><b>'+G.length+'</b><span>гостей всего</span></div><div class="card kpi"><b>'+rep+'</b><span>вернулись повторно</span></div><div class="card kpi"><b>$'+Math.round(tot)+'</b><span>сумма броней</span></div><div class="card kpi"><b>'+G.filter(function(g){return g.profile}).length+'</b><span>с профилем −5%</span></div></div>'+
  '<div class="card">'+(L.map(function(g){return '<div class="g-card"><div class="av">'+esc((g.name||'?')[0])+'</div><div><b>'+esc(g.name)+(g.bookings>1?' <span class="pill paid">'+g.bookings+' брони</span>':'')+(g.tg?' <i class="ph-fill ph-telegram-logo" style="color:#2AABEE"></i>':'')+(g.profile?' <span class="pill src">профиль −'+g.discount+'%</span>':'')+'</b><small>'+esc(g.phone)+(g.email?' · '+esc(g.email):'')+'</small><small>'+Object.keys(g.apts).map(aptName).map(esc).join(', ')+' · последняя '+fmtD(g.last.slice(0,10))+(g.cancelled?' · отмен: '+g.cancelled:'')+'</small></div><div class="nums"><b>$'+Math.round(g.spent)+'</b><small>'+g.nights+' '+nw(g.nights)+'</small></div></div>'}).join('')||'<div class="empty">'+(q?'Не найдено':'Гостей пока нет')+'</div>')+'</div>';
  var qt;$('#gQ').oninput=function(){gQ=this.value;clearTimeout(qt);qt=setTimeout(function(){rGuests(v);keepFocus('#gQ')},300)};
  $('#gCsv').onclick=function(){var rows=[['Имя','Телефон','Email','Мессенджер','Броней','Ночей','Сумма $','Отмен','Первая бронь','Последняя бронь','Апартаменты','Telegram-бот','Профиль']].concat(G.map(function(g){return [g.name,g.phone,g.email,g.messenger,g.bookings,g.nights,Math.round(g.spent),g.cancelled,g.first.slice(0,10),g.last.slice(0,10),Object.keys(g.apts).join(' '),g.tg?'да':'нет',g.profile?'да':'нет']}));var csv='\ufeff'+rows.map(function(r){return r.map(function(x){return '"'+String(x==null?'':x).replace(/"/g,'""')+'"'}).join(';')}).join('\n');var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='novahome-guests-'+today()+'.csv';a.click()}}).catch(function(e){errCard(v,e,function(){rGuests(v)})})}

