  v.innerHTML='<div class="page-h"><h1>Блог</h1><div class="acts"><button class="icon" id="addPost"><i class="ph-bold ph-plus"></i></button></div></div>'+(P.length?'<div class="card"><table class="list"><thead><tr><th>Статья</th><th>Рубрика</th><th>Дата</th><th>Статус</th></tr></thead><tbody>'+P.map(function(p,i){return '<tr class="rowlink" data-i="'+i+'"><td><div class="lst"><div class="th" style="'+(p.cover?'background-image:url('+IMG(p.cover)+')':'')+'">'+(p.cover?'':'<i class="ph-bold ph-image"></i>')+'</div><div><b>'+esc(p.title||'Без названия')+'</b><small>'+esc(p.excerpt||'').slice(0,70)+'</small></div></div></td><td>'+esc(p.cat||'—')+'</td><td>'+fmtD(p.date)+'</td><td><span class="st '+(p.published?'ok':'off')+'">'+(p.published?'Опубликована':'Черновик')+'</span></td></tr>'}).join('')+'</tbody></table></div>':'<div class="card empty">Статей пока нет. Три статьи из кода сайта останутся; новые появятся выше них.</div>');
  $('#addPost').onclick=function(){P.unshift({slug:'post-'+Date.now().toString(36),title:'',cat:'Советы',excerpt:'',body:'',cover:'',min:3,date:today(),published:false});markDirty();S.blogEdit=0;render()};
